import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

/** Primary key: random UUID generated by the database. */
export const id = () => uuid().primaryKey().defaultRandom();

export const createdAt = () => timestamp({ withTimezone: true, mode: 'date' }).notNull().defaultNow();
export const updatedAt = () => timestamp({ withTimezone: true, mode: 'date' }).notNull().defaultNow();
export const timestamptz = () => timestamp({ withTimezone: true, mode: 'date' });

/** PostgreSQL full-text search vector. Always written by SQL (to_tsvector), never by application code. */
export const tsvector = customType<{ data: string; driverData: string }>({
  dataType() {
    return 'tsvector';
  },
});

/**
 * Data integrity classes (specification section 16). Every metric, score and observation
 * carries exactly one of these so that verified facts are never mixed with estimates.
 */
export const DATA_CLASSES = ['verified', 'calculated', 'ai_assessed', 'estimated', 'missing'] as const;
export type DataClass = (typeof DATA_CLASSES)[number];

/** How a marketplace observation was collected (specification section 9, in priority order). */
export const COLLECTION_METHODS = [
  'official_api',
  'authorised_data_provider',
  'retailer_integration',
  'permitted_public_collection',
  'manual_upload',
] as const;
export type CollectionMethod = (typeof COLLECTION_METHODS)[number];

export const CONFIDENCE_LEVELS = ['high', 'medium', 'low'] as const;
export type Confidence = (typeof CONFIDENCE_LEVELS)[number];
